import { config } from "@/config/env";
import type { BoletoCharge, ChargeStatus, InvoiceDetail, InvoiceFilters, InvoiceSummary, PaymentRecord, PixCharge } from "@/types/domain";
import { mockInvoiceService } from "./mock/invoice.mock";
import { remoteInvoiceService } from "./remote/invoice.remote";

/**
 * Invoices & payments — READ-ONLY. The app never creates invoices, Pix, boletos, charges or any
 * financial record: they are generated by the ACVEL systems; the app only reads and displays them.
 * API (rateio, GET only): /v1/faturas/me, /v1/faturas/{id}, /v1/faturas/{id}/pdf (Bearer, binary),
 *   /v1/pagamentos/cobrancas?fatura_id= (existing bank charge — Pix + boleto — of an invoice),
 *   /v1/pagamentos/cobrancas?status=CONFIRMADO (payment history).
 * API (business, GET): /v1/consumidores/me/rateio-snapshot (fallback list, kWh/savings, payment history).
 */
export interface InvoiceService {
  getInvoices(filters: InvoiceFilters): Promise<InvoiceSummary[]>;
  getInvoice(invoiceId: string): Promise<InvoiceDetail>;
  /** Downloads the existing official PDF and returns a local file URI. */
  downloadInvoicePdf(invoiceId: string): Promise<string>;
  /** The invoice's existing Pix (payload + expiry) as returned by the backend; never requests a new one. */
  getExistingPix(invoiceId: string): Promise<PixCharge>;
  /** Reads the current status of the existing charge (polled while the Pix screen is open). */
  getPaymentStatus(invoiceId: string): Promise<ChargeStatus>;
  /** The invoice's existing boleto (digitable line, barcode); never registers one. */
  getExistingBoleto(invoiceId: string): Promise<BoletoCharge>;
  getPaymentHistory(): Promise<PaymentRecord[]>;
}

export const invoiceService: InvoiceService = config.useMocks ? mockInvoiceService : remoteInvoiceService;
